#!/bin/bash
# Transcribed from the run record: the code ran as a shell heredoc or a one-line command, so no script file existed on disk.
# Cuts the unit maps of the 19 new trio reference slots (g8trio: 18, g8trio2: hg003 slot 2) with the deposited
# consmapG8v4_fixdedup.py (U2) at the same settings (asm20, LO 2100, HI 2400, FRAG 5, PAD 100, CTX 200);
# run_rjf_trio.sh then joins them with the fix-1 map. Inputs new_rows.tsv / hap_seq_node_trio.tsv come from prep_canon_trio.sh.
# Only the commands run on the node are kept (ssh wrapper removed). Not re-run here (node). Logs of (a): G8 rc=0, G6 rc=0.
# (a) 2026-09-18 14:18 UTC, record line 52743 — G8 (unit map) and G6 maps for the 18 changed/new slots of new_rows.tsv
cd ~ && T=~/trio_v11 && [ ! -e $T/g8trio ] && [ ! -e $T/g6trio ] && mkdir -p $T/g8trio $T/g6trio && HSN=$T/hap_seq_node_trio.tsv CMPD=$T/cmp4d_trio WDIR=$T/g8trio TAG=trio PRESET=asm20 TH=8 LO=2100 HI=2400 FRAG=5 PAD=100 CTX=200 PYTHONIOENCODING=utf-8 python3 ~/consmapG8v4_fixdedup.py $T/new_rows.tsv > $T/g8trio/trio.out 2> $T/g8trio/trio.err; echo "G8 rc=$?"; tail -3 $T/g8trio/trio.out; ls $T/g8trio; HSN=$T/new_rows.tsv CMPD=$T/cmp4d_trio WDIR=$T/g6trio TAG=trio TH=8 PYTHONIOENCODING=utf-8 python3 ~/consmapG6_env.py 1 0 > $T/g6trio/trio.out 2> $T/g6trio/trio.err; echo "G6 rc=$?"; ls $T/g6trio; tail -3 $T/g6trio/trio.err

