#     (this command stopped at `diff` under set -e, before cutting; (c) cut the maps)
set -e; T=~/trio_v11; C=$T/cmp4d_trio; N=trioinf__58__hiarr_hg002_3_as_hg003_2.fa; [ -e $C/$N ] && { echo 이미; exit 1; }; cp ~/hiasm/arr/hiarr_hg002_3.fa $C/$N; cmp -s ~/hiasm/arr/hiarr_hg002_3.fa $C/$N && echo "복사 동일 $(md5sum < $C/$N | cut -c1-8)"; echo "Q100 부계와 서열 동일 확인: $(tail -n +2 ~/asmarr/arr_HG002_1.fa | tr -d "\n" | md5sum | cut -c1-8) vs $(tail -n +2 $C/$N | tr -d "\n" | md5sum | cut -c1-8)"; [ -e $T/hap_seq_node_trio2.tsv ] && exit 1; awk -F"\t" -v n=$N "BEGIN{OFS=\"\t\"} \$1==\"hg003\" && \$2==\"2\" {\$3=n} {print}" $T/hap_seq_node_trio.tsv > $T/hap_seq_node_trio2.tsv; diff $T/hap_seq_node_trio.tsv $T/hap_seq_node_trio2.tsv; printf "hg003\t2\t$N\n" > $T/new_rows2.tsv; mkdir $T/g8trio2 $T/g6trio2; cd ~; HSN=$T/hap_seq_node_trio2.tsv CMPD=$C WDIR=$T/g8trio2 TAG=trio2 PRESET=asm20 TH=8 LO=2100 HI=2400 FRAG=5 PAD=100 CTX=200 PYTHONIOENCODING=utf-8 python3 ~/consmapG8v4_fixdedup.py $T/new_rows2.tsv > $T/g8trio2/o.txt 2> $T/g8trio2/e.txt; HSN=$T/new_rows2.tsv CMPD=$C WDIR=$T/g6trio2 TAG=trio2 TH=8 python3 ~/consmapG6_env.py 1 0 > /dev/null 2>&1; cut -f1-8 $T/g8trio2/CONSENSUS_SUM_G8_trio2.tsv; cut -f1-9 $T/g6trio2/sum_trio2.tsv; echo "G8 hg002 슬롯2 행과 변이열 비교:"; diff <(awk -F"\t" "\$1==\"hg002\"&&\$2==\"2\"" $T/g8trio/CONSENSUS_MAP_G8_trio.tsv | cut -f4-) <(awk -F"\t" "\$1==\"hg003\"&&\$2==\"2\"" $T/g8trio2/CONSENSUS_MAP_G8_trio2.tsv | cut -f4-) | wc -l

